DROP TABLE IF EXISTS `saved_results`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `saved_results` (
  `id` bigint NOT NULL AUTO_INCREMENT,
  `share_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL,
  `user_id` bigint DEFAULT NULL,
  `result_json` text COLLATE utf8mb4_unicode_ci NOT NULL,
  `net_annual_savings` decimal(10,2) DEFAULT '0.00',
  `annual_reward` decimal(10,2) DEFAULT '0.00',
  `total_annual_fees` decimal(10,2) DEFAULT '0.00',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP,
  `expires_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `share_id` (`share_id`),
  KEY `idx_share_id` (`share_id`),
  KEY `idx_user_id` (`user_id`)
) ENGINE=InnoDB AUTO_INCREMENT=5 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

